// ── Primitives ──────────────────────────────────────────────────────────────

function Btn({ children, onClick, active, danger, primary, small, primed, ...rest }) {
  return (
    <button onClick={onClick} {...rest}
    className={`pp-btn ${active ? 'pp-btn-on' : ''} ${danger ? 'pp-btn-danger' : ''} ${primary ? 'pp-btn-primary' : ''} ${small ? 'pp-btn-sm' : ''} ${primed ? 'pp-btn-primed' : ''}`}>
      {children}
    </button>);

}

function Tag({ children, dot, mono, accent }) {
  return (
    <span className={`pp-tag ${mono ? 'pp-tag-mono' : ''} ${accent ? 'pp-tag-accent' : ''}`}>
      {dot && <span className="pp-dot" />}
      {children}
    </span>);

}

function Hr({ label }) {
  if (!label) return <hr className="pp-hr" />;
  return (
    <div className="pp-hr-l">
      <span className="pp-hr-line" />
      <span className="pp-hr-label">{label}</span>
      <span className="pp-hr-line" />
    </div>);

}

function Spec({ label, value, sub }) {
  return (
    <div className="pp-spec">
      <div className="pp-spec-l">{label}</div>
      <div className="pp-spec-v">{value}</div>
      {sub && <div className="pp-spec-s">{sub}</div>}
    </div>);

}

function Label({ children, n }) {
  return <div className="pp-label">{n && <span className="pp-label-n">{n}</span>}{children}</div>;
}

// Glyphs — simple 1px-stroke brutalist symbols.
// Sized to match the call-control button cap height.
function WaveGlyph({ size = 14 }) {
  // Audio waveform bars — start a voice call. (DS renamed PhoneGlyph → WaveGlyph:
  // the call-start affordance is bars, not a handset.)
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.6" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      <line x1="2" y1="6.5" x2="2" y2="9.5" />
      <line x1="5" y1="4.5" x2="5" y2="11.5" />
      <line x1="8" y1="2.5" x2="8" y2="13.5" />
      <line x1="11" y1="4.5" x2="11" y2="11.5" />
      <line x1="14" y1="6.5" x2="14" y2="9.5" />
    </svg>);

}
function PhoneHangGlyph({ size = 14 }) {
  // Hang up — clean cross. Universal "end".
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="2" strokeLinecap="square"
    aria-hidden="true" style={{ display: 'block' }}>
      <line x1="3" y1="3" x2="13" y2="13" />
      <line x1="13" y1="3" x2="3" y2="13" />
    </svg>);

}
function MicGlyph({ size = 14, muted = false }) {
  // Mic body + stand. Mute state adds a diagonal slash.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.4" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      <rect x="6" y="2" width="4" height="8" />
      <path d="M3.5 8.5a4.5 4.5 0 0 0 9 0" />
      <line x1="8" y1="13" x2="8" y2="15" />
      <line x1="5.5" y1="15" x2="10.5" y2="15" />
      {muted && <line x1="2.5" y1="2.5" x2="13.5" y2="13.5" strokeWidth="1.8" />}
    </svg>);

}
function WrenchGlyph({ size = 14 }) {
  // Open-end wrench at 45°. 1.4px stroke, brutalist square caps.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.4" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      <line x1="3" y1="13" x2="9" y2="7" />
      <path d="M9.5 6.5 L12 4 L13.2 5.2 L13.2 7.2 L11.2 7.2 L10 8.4 Z" />
    </svg>);

}
function ScrollGlyph({ size = 14 }) {
  // Paper scroll — top + bottom rolled edges, text lines in the middle.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.4" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      {/* Top roll */}
      <rect x="2.5" y="2" width="11" height="2" />
      {/* Body */}
      <line x1="3.5" y1="4" x2="3.5" y2="12" />
      <line x1="12.5" y1="4" x2="12.5" y2="12" />
      <line x1="5" y1="6.5" x2="11" y2="6.5" />
      <line x1="5" y1="9" x2="11" y2="9" />
      {/* Bottom roll */}
      <rect x="2.5" y="12" width="11" height="2" />
    </svg>);

}
function SendGlyph({ size = 14 }) {
  // Arrow into an end-bar — "send / commit my turn". Mirrors the codebase's
  // SendGlyph; rendered only for the half-duplex cascade STT engine.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.6" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      <line x1="2" y1="8" x2="10" y2="8" />
      <path d="M7 5 L10 8 L7 11" />
      <line x1="13" y1="3.5" x2="13" y2="12.5" />
    </svg>);

}
function InterruptGlyph({ size = 14 }) {
  // Open palm — universal "stop / hold on, let me talk".
  // Brutalist square edges, 1.4px stroke.
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.4" strokeLinecap="square" strokeLinejoin="miter"
    aria-hidden="true" style={{ display: 'block' }}>
      {/* palm */}
      <path d="M5 8V3.5a1 1 0 0 1 2 0V7" />
      <path d="M7 7V2.5a1 1 0 0 1 2 0V7" />
      <path d="M9 7V3a1 1 0 0 1 2 0v5" />
      <path d="M11 5.5a1 1 0 0 1 2 0V10a4 4 0 0 1-4 4H8a3 3 0 0 1-2.6-1.5L3 8.5a1 1 0 0 1 1.7-1L6 9" />
    </svg>);

}

// ── Call View ───────────────────────────────────────────────────────────────

function CallView({ tweaks, callState, setCallState, persona, provider, dark, compact, tools, setTools, muted, setMuted, failover }) {
  const [transcriptOpen, setTranscriptOpen] = useState(tweaks.transcript === 'drawer');
  const [toolsOpen, setToolsOpen] = useState(false);
  // Pretend we're deep into a session so the transcript actually has scroll content.
  const [transcriptIdx, setTranscriptIdx] = useState(TRANSCRIPT_SCRIPT.length - 1);
  const [caption, setCaption] = useState(TRANSCRIPT_SCRIPT[2].text);

  // Only the cascade STT engine has a manual end-of-turn (half-duplex). Mirrors
  // the codebase's session.canSendTurn (engine === 'cascade').
  const canSendTurn = provider.engine === 'cascade';
  // Mirrors the codebase's session.sendTurnEnabled: the design mock simply
  // tracks LISTENING, while the app keeps SEND armed through dead-air capture
  // (VAD closed, reply not yet committed) so late speech still lands.
  const sendTurnEnabled = canSendTurn && callState === 'listening';

  // sync caption with state
  useEffect(() => {
    if (callState === 'idle' || callState === 'ended') {
      setCaption(callState === 'ended' ? '— call ended —' : 'press CALL to begin');
      return;
    }
    if (callState === 'connecting') {setCaption('establishing session…');return;}
    if (callState === 'listening') {setCaption(TRANSCRIPT_SCRIPT[TRANSCRIPT_SCRIPT.length - 2].text);return;}
    if (callState === 'speaking') {setCaption(TRANSCRIPT_SCRIPT[TRANSCRIPT_SCRIPT.length - 1].text);return;}
    if (callState === 'interrupted') {setCaption('… you interrupted');return;}
  }, [callState]);

  // mock elapsed-time ticker
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    if (callState === 'idle' || callState === 'ended') {setElapsed(0);return;}
    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
    return () => clearInterval(t);
  }, [callState]);

  const visible = TRANSCRIPT_SCRIPT.slice(0, transcriptIdx + 1);

  const handleCall = () => {
    if (callState === 'idle' || callState === 'ended') {
      setCallState('connecting');
      setTimeout(() => setCallState('listening'), 1400);
      setTimeout(() => setCallState('speaking'), 3600);
    } else {
      setCallState('ended');
    }
  };

  const handleInterrupt = () => {
    if (callState === 'speaking') {
      setCallState('interrupted');
      setTimeout(() => setCallState('listening'), 900);
    }
  };

  // Commit the user's turn (cascade STT): close listening, let the agent reply.
  const handleSendTurn = () => {
    if (sendTurnEnabled) setCallState('speaking');
  };

  const stateLabel = {
    idle: 'IDLE',
    connecting: 'CONNECTING',
    listening: 'LISTENING',
    speaking: 'SPEAKING',
    interrupted: 'INTERRUPTED',
    ended: 'ENDED'
  }[callState];

  return (
    <div className="pp-call">
      <div className="pp-call-stage">

        {/* Top status row */}
        <div className="pp-call-meta">
          <div className="pp-call-meta-l">
            <Tag mono dot>SESSION · {String(elapsed).padStart(2, '0').slice(-2)}:{String(elapsed % 60).padStart(2, '0')}</Tag>
            {tweaks.providerPreview && <Tag mono>VIA {provider.name} · {provider.model}</Tag>}
          </div>
          <div className="pp-call-meta-r">
            <Tag mono>PERSONA · {persona.name}{persona.lang === 'ja' ? ' · JA' : ''}</Tag>
            {persona.lang === 'ja' && !provider.ja &&
            <Tag mono accent>NO JA ON {provider.name} · FAILOVER</Tag>
            }
          </div>
        </div>

        {/* Transport failover strip — JA persona armed on an EN-only transport.
               Session stays up: state dips to CONNECTING while the stream re-anchors,
               then the strip flips to REROUTED and clears. */}
        {failover &&
        <div className={`pp-failover ${failover.phase}`} role="status">
          {failover.phase === 'switching' ?
          <>▲ JA VOICE UNSUPPORTED ON {failover.from} — REROUTING TRANSPORT → {failover.to}</> :
          <>● TRANSPORT REROUTED → {failover.to} · JA VOICE · SESSION RESUMED</>}
        </div>
        }

        {/* Main body — vertically split 50/50: orb area on top, caption on bottom.
               The 50/50 split keeps the caption legible even when long, and the orb
               scales to fit its half via container queries. */}
        <div className="pp-call-body">

          {/* Orb half */}
          <div className="pp-orb-area">
            <div className="pp-orb-fit">
              <Orb state={callState} style={tweaks.orbStyle} size="100%" accent={tweaks.accent} dark={dark} manual={canSendTurn} />
            </div>
            {(callState === 'listening' || callState === 'interrupted') && <Soundbars count={10} />}
            <div className="pp-call-state">
              <span className={`pp-call-state-dot pp-state-${callState}`} />
              <span className="pp-call-state-l">{stateLabel}</span>
              {callState !== 'idle' && callState !== 'ended' && <span className="pp-call-state-sub">— {persona.name.toLowerCase()} · {provider.name.toLowerCase()}</span>}
            </div>
            {sendTurnEnabled &&
            <div className="pp-call-manual-hint">MANUAL TURN · PRESS SEND TO REPLY</div>
            }
          </div>

          {/* Caption half — scrollable text area with macOS-style auto-hiding indicator */}
          {tweaks.transcript !== 'off' &&
          <div className="pp-caption-area">
              <ScrollArea className="pp-caption-scroll" dark={dark}>
                <div className="pp-caption" key={caption}>
                  <span className="pp-caption-q">“</span>
                  <span className="pp-caption-t">{caption}</span>
                  <span className="pp-caption-q">”</span>
                </div>
              </ScrollArea>
            </div>
          }
        </div>

        {/* Controls */}
        <div className="pp-controls">
          <Btn small onClick={() => setMuted(!muted)} active={muted}
          aria-label={muted ? 'Unmute microphone' : 'Mute microphone'}>
            <MicGlyph muted={muted} />
          </Btn>
          <Btn small onClick={handleInterrupt} disabled={callState !== 'speaking'}
          aria-label="Interrupt agent">
            <InterruptGlyph />
          </Btn>
          {canSendTurn &&
          <Btn small primed={sendTurnEnabled} onClick={handleSendTurn} disabled={!sendTurnEnabled}
          aria-label="Send turn">
              <SendGlyph />
            </Btn>
          }
          <Btn primary onClick={handleCall} danger={!(callState === 'idle' || callState === 'ended')}
          aria-label={callState === 'idle' || callState === 'ended' ? 'Call' : 'Hang up'}>
            {callState === 'idle' || callState === 'ended' ? <WaveGlyph /> : <PhoneHangGlyph />}
          </Btn>
          {tweaks.transcript === 'drawer' &&
          <Btn small onClick={() => setTranscriptOpen((o) => !o)} active={transcriptOpen}
          aria-label={transcriptOpen ? 'Hide transcript' : 'Show transcript'}>
              <ScrollGlyph />
            </Btn>
          }
          <ToolsButton tools={tools} open={toolsOpen} setOpen={setToolsOpen} />
        </div>

      </div>

      {/* Transcript drawer */}
      {tweaks.transcript === 'drawer' &&
      <aside className={`pp-transcript ${transcriptOpen ? 'open' : ''}`}>
          <div className="pp-transcript-hd">
            <span className="pp-h-eyebrow">LIVE TRANSCRIPT</span>
            <span className="pp-h-meta">{visible.length} TURNS · {provider.model}</span>
          </div>
          <ScrollArea className="pp-transcript-scroll" dark={dark}>
            <div className="pp-transcript-body">
              {visible.map((t, i) =>
            <div key={i} className={`pp-turn pp-turn-${t.who}`}>
                  <div className="pp-turn-hd">
                    <span className="pp-turn-who">{t.who === 'user' ? 'YOU' : persona.name}</span>
                    <span className="pp-turn-t">00:{String(i * 7).padStart(2, '0')}</span>
                  </div>
                  <div className="pp-turn-text">{t.text}</div>
                </div>
            )}
              {callState === 'speaking' &&
            <div className="pp-turn pp-turn-agent pp-turn-live">
                  <div className="pp-turn-hd">
                    <span className="pp-turn-who">{persona.name}</span>
                    <span className="pp-turn-t">— LIVE —</span>
                  </div>
                  <div className="pp-turn-text"><span className="pp-cursor" /></div>
                </div>
            }
            </div>
          </ScrollArea>
        </aside>
      }
    </div>);

}

// ── Personas View ───────────────────────────────────────────────────────────

// EN / 日本語 flip on every persona card. stopPropagation so flipping the
// language never steals the card's select-click.
function LangSwitch({ lang, onChange, compact }) {
  return (
    <span className="pp-lang-sw" role="group" aria-label="Voice language">
      {[['en', 'EN'], ['ja', compact ? 'JA' : '日本語']].map(([id, label]) =>
      <button key={id} type="button"
      className={`pp-lang-btn ${lang === id ? 'on' : ''} ${id === 'ja' ? 'pp-ja' : ''}`}
      aria-pressed={lang === id}
      onClick={(e) => {e.stopPropagation();onChange(id);}}>{label}</button>
      )}
    </span>);
}

const JA_VENDORS = () => PROVIDERS.filter((p) => p.ja).map((p) => p.name).join(' · ');

function PersonasView({ persona, setPersona, provider, dark, accent }) {
  // Per-card language map. Seeded from the armed persona so navigating away
  // and back doesn't silently disagree with the active selection.
  const [langs, setLangs] = useState(() => persona.lang === 'ja' ? { [persona.id]: 'ja' } : {});
  const setLang = (p, lang) => {
    setLangs((prev) => ({ ...prev, [p.id]: lang }));
    if (persona.id === p.id) setPersona(resolvePersona(p, lang));
  };
  return (
    <div className="pp-personas">
      <div className="pp-page-hd">
        <div>
          <div className="pp-h-eyebrow">001 / VOICE LIBRARY</div>
          <h1 className="pp-h1">Personas.</h1>
          <p className="pp-lede">One ancient camellia spirit. Seven named manifestations — each speaks English or Japanese. Selection persists across providers.</p>
        </div>
        <div className="pp-page-hd-r">
          <Btn small>+ CLONE NEW</Btn>
          <Btn small>IMPORT</Btn>
        </div>
      </div>

      <div className="pp-grid">
        {PERSONAS.map((p, i) => {
          const lang = langs[p.id] || 'en';
          const r = resolvePersona(p, lang);
          const on = persona.id === p.id;
          const ja = r.lang === 'ja';
          const mismatch = on && ja && !provider.ja;
          return (
        <div
          key={p.id}
          className={`pp-persona-card ${on ? 'on' : ''}`}
          onClick={() => setPersona(r)}>
            <div className="pp-persona-top">
              <div className="pp-persona-num">{String(i + 1).padStart(2, '0')}</div>
              <div className="pp-persona-top-r">
                <LangSwitch lang={lang} onChange={(l) => setLang(p, l)} />
                <div
              className="pp-persona-dot"
              style={{
                background: on ? accent : `color-mix(in srgb, ${accent} 26%, #000)`,
                boxShadow: on ? `0 0 0 4px color-mix(in srgb, ${accent} 22%, transparent)` : 'none'
              }}
              role="img"
              aria-label={on ? 'Active persona' : 'Inactive persona'}
              title={on ? 'Active' : 'Inactive'} />
              </div>
            </div>
            <div className="pp-persona-name">
              {ja ? <span className="pp-ja">{r.name}</span> : r.name}
              {ja && <span className="pp-name-sub">{p.name}</span>}
            </div>
            <div className="pp-persona-accent">{r.accent} · <span className={ja ? 'pp-ja' : ''}>{r.aspect}</span></div>
            <div className="pp-persona-traits">
              {r.traits.map((t) => <span key={t} className={`pp-trait ${ja ? 'pp-ja' : ''}`}>{t}</span>)}
            </div>
            <p className={`pp-persona-desc ${ja ? 'pp-ja' : ''}`}>{r.desc}</p>
            {ja &&
            <div className="pp-ja-support">
              <span className="pp-ja-support-l">JA VOICE</span>
              <span className="pp-ja-support-v">{JA_VENDORS()}</span>
            </div>
            }
            {mismatch &&
            <div className="pp-ja-warn">▲ ACTIVE TRANSPORT {provider.name} — NO JA · FAILOVER → OPENAI</div>
            }
            <div className="pp-persona-foot">
              <span className="pp-mono-num">{r.rateLabel}</span>
              <span className="pp-mono-num">{p.voice}</span>
            </div>
          </div>);
        })}

        {/* Clone slot */}
        <div className="pp-persona-card pp-persona-empty">
          <div className="pp-persona-num">+</div>
          <div className="pp-persona-name">EMPTY SLOT</div>
          <p className="pp-persona-desc">Drop a 30-second voice sample to clone. Consent prompt is run end-to-end.</p>
          <div className="pp-persona-drop">
            <span>DRAG · .wav · .mp3 · ≤ 30s</span>
          </div>
        </div>
      </div>
    </div>);

}

// ── Providers View ──────────────────────────────────────────────────────────

function ProvidersView({ provider, setProvider, accent }) {
  // Surface the two headline transport changes in the active-provider detail:
  // the cascade engine (STT→LM→TTS) and neural Silero VAD turn detection.
  const isCascade = provider.engine === 'cascade';
  // Runtime-selected cascade LM model. The codebase persists this (localStorage);
  // the design keeps it local. Only engines with a multi-model catalog show the
  // picker, so it lives on this screen rather than in global app state.
  const [lmModelId, setLmModelId] = useState(LM_MODELS[0].id);
  // The cascade's EXECUTION cell follows the LM picker live (TTS/STT legs come
  // from the voice catalog defaults).
  const lmBackend = (LM_MODELS.find((m) => m.id === lmModelId) || LM_MODELS[0]).backend;

  return (
    <div className="pp-providers">
      <div className="pp-page-hd">
        <div>
          <div className="pp-h-eyebrow">002 / TRANSPORT</div>
          <h1 className="pp-h1">Realtime providers.</h1>
          <p className="pp-lede">All seven backends accept the same audio stream. Switch mid-call without dropping the session.</p>
        </div>
        <div className="pp-page-hd-r">
          <Tag mono dot>AUTO-FAILOVER ON</Tag>
        </div>
      </div>

      <table className="pp-table">
        <thead>
          <tr>
            <th style={{ width: 32 }}></th>
            <th>VENDOR</th>
            <th>MODEL</th>
            <th data-comment-anchor="a006cb200f-th-474-13">EXECUTION</th>
            <th>NOTES</th>
          </tr>
        </thead>
        <tbody>
          {PROVIDERS.map((p, i) => {
            const on = provider.id === p.id;
            // Only engines with a multi-model catalog (cascade) get a picker inset;
            // single-model / unconfigurable providers render no inset row.
            const models = p.engine === 'cascade' ? LM_MODELS : [];
            return (
            <React.Fragment key={p.id}>
              <tr className={on ? 'on' : ''} onClick={() => setProvider(p)}>
                <td className="pp-table-radio">
                  <span className={on ? 'on' : ''} style={on ? { background: accent, borderColor: accent } : null} />
                </td>
                <td className="pp-table-vendor">{p.name}{p.ja && <span className="pp-ja-mark" title="Japanese realtime voices">JA</span>}</td>
                <td className="pp-mono-num">{providerModelLabel(p, lmModelId)}</td>
                <td>
                  <Tag mono dot>{providerExecLabel(p, lmBackend).toUpperCase()}</Tag>
                </td>
                <td className="pp-table-note">{p.note}</td>
              </tr>
              {models.length > 1 &&
              <tr className={`pp-prov-inset-row ${on ? 'on' : ''}`}>
                <td></td>
                <td colSpan={4} className="pp-prov-inset">
                  <div className="pp-prov-inset-inner">
                    <span className="pp-prov-inset-l">LM MODEL</span>
                    <span className="pp-prov-models">
                      {models.map((m) => {
                        const sel = m.id === lmModelId;
                        return (
                        <button key={m.id} type="button"
                        className={`pp-prov-model ${sel ? 'on' : ''}`}
                        style={sel ? { borderColor: accent, color: accent } : null}
                        aria-pressed={sel}
                        onClick={(e) => {e.stopPropagation();setLmModelId(m.id);}}>
                          {m.label}
                        </button>);
                      })}
                    </span>
                  </div>
                </td>
              </tr>
              }
            </React.Fragment>);
          })}
        </tbody>
      </table>

      <div className="pp-prov-detail">
        <Hr label={`ACTIVE · ${provider.name}`} />
        <div className="pp-prov-specs">
          <Spec label="ENGINE"
          value={provider.engine ? provider.engine.toUpperCase() : 'MOCK'}
          sub={isCascade ? 'STT → LM → TTS' : provider.engine ? 'native realtime' : 'design preview'} />
          {isCascade ?
          <Spec label="VOICE LEGS"
          value={`TTS ${TTS_BACKEND.toUpperCase()} · STT ${STT_BACKEND.toUpperCase()}`}
          sub="NEXT_PUBLIC_*_BACKEND · voice-models.json" /> :
          <Spec label="CODEC" value="opus 48k mono" sub="server-side resample" />
          }
          <Spec label="TURN DETECTION"
          value={isCascade ? 'Silero VAD' : 'server VAD'}
          sub={isCascade ? 'neural · browser · send-turn' : '200 ms silence → end-of-turn'} />
          <Spec label="TOOL FORMAT" value="OpenAI-style fn-calls" sub="translated per provider" />
        </div>
      </div>
    </div>);

}

// ── Settings View ───────────────────────────────────────────────────────────

function SettingsView({ accent, tools, setTools, muted, setMuted }) {
  const [mic, setMic] = useState('MacBook Pro Microphone');
  const [out, setOut] = useState('AirPods Pro · Erik');
  const [latency, setLatency] = useState(220);
  const [vadSensitivity, setVad] = useState(0.65);
  const [denoise, setDenoise] = useState(true);
  const [interruptions, setInterruptions] = useState(true);
  const [pushToTalk, setPushToTalk] = useState(false);

  const toggleTool = (name) => {
    setTools((prev) => prev.map((t) => t.name === name ? { ...t, on: !t.on } : t));
  };

  return (
    <div className="pp-settings">
      <div className="pp-page-hd">
        <div>
          <div className="pp-h-eyebrow">003 / CONFIGURATION</div>
          <h1 className="pp-h1">Settings.</h1>
          <p className="pp-lede">Local audio chain, model behaviour, tools and safety.</p>
        </div>
      </div>

      <div className="pp-settings-grid">

        <section className="pp-settings-sec">
          <Hr label="AUDIO IN" />
          <FieldRow label="INPUT DEVICE">
            <MicSelector value={mic} onChange={setMic} muted={muted} onMutedChange={setMuted} />
          </FieldRow>
          <FieldRow label="LEVEL">
            <div className="pp-meter">
              <span style={{ width: '58%', background: accent }} />
            </div>
          </FieldRow>
          <FieldRow label="DENOISE">
            <SwitchRow value={denoise} onChange={setDenoise} />
          </FieldRow>
          <FieldRow label="VAD SENSITIVITY" hint={`${vadSensitivity.toFixed(2)} · medium`}>
            <input type="range" min="0" max="1" step="0.01" value={vadSensitivity}
            onChange={(e) => setVad(parseFloat(e.target.value))} className="pp-range"
            style={{ accentColor: accent }} />
          </FieldRow>
        </section>

        <section className="pp-settings-sec">
          <Hr label="AUDIO OUT" />
          <FieldRow label="OUTPUT DEVICE">
            <select className="pp-select" value={out} onChange={(e) => setOut(e.target.value)}>
              <option>AirPods Pro · Erik</option>
              <option>MacBook Pro Speakers</option>
              <option>Studio Monitors L/R</option>
            </select>
          </FieldRow>
          <FieldRow label="VOLUME">
            <input type="range" defaultValue="70" className="pp-range" style={{ accentColor: accent }} />
          </FieldRow>
          <FieldRow label="SPATIAL">
            <SwitchRow value={false} onChange={() => {}} />
          </FieldRow>
        </section>

        <section className="pp-settings-sec">
          <Hr label="BEHAVIOUR" />
          <FieldRow label="LATENCY BUDGET" hint={`${latency} ms · balanced`}>
            <input type="range" min="80" max="600" step="10" value={latency}
            onChange={(e) => setLatency(parseInt(e.target.value))} className="pp-range"
            style={{ accentColor: accent }} />
            <div className="pp-range-scale">
              <span>80</span><span>240</span><span>400</span><span>600</span>
            </div>
          </FieldRow>
          <FieldRow label="INTERRUPTIONS" hint="voice barge-in · headphones only">
            <SwitchRow value={interruptions} onChange={setInterruptions} />
          </FieldRow>
          <FieldRow label="PUSH-TO-TALK" hint="cascade · send button ends your turn">
            <SwitchRow value={pushToTalk} onChange={setPushToTalk} />
          </FieldRow>
        </section>

        <section className="pp-settings-sec">
          <Hr label="TOOLS" />
          {tools.map((t) =>
          <ToolRow key={t.name} name={t.name} label={t.label} on={t.on}
          onToggle={() => toggleTool(t.name)} />
          )}
        </section>
      </div>
    </div>);

}

function FieldRow({ label, hint, children }) {
  return (
    <div className="pp-field">
      <div className="pp-field-hd">
        <span className="pp-field-l">{label}</span>
        {hint && <span className="pp-field-hint">{hint}</span>}
      </div>
      <div className="pp-field-c">{children}</div>
    </div>);

}

function SwitchRow({ value, onChange }) {
  return (
    <button className={`pp-switch ${value ? 'on' : ''}`} onClick={() => onChange(!value)}>
      <span className="pp-switch-l">OFF</span>
      <span className="pp-switch-knob" />
      <span className="pp-switch-r">ON</span>
    </button>);

}

// ── MicSelector ─────────────────────────────────────────────────────────────
// Mic icon (toggles mute) + device label + chevron. Click opens a popover
// listing devices with a static waveform preview at the bottom — matches the
// codebase's ElevenLabs-derived MicSelector but rendered in brutalist chrome.

const MOCK_INPUT_DEVICES = [
'MacBook Pro Microphone',
'iPhone Mic',
'AirPods Pro · Erik',
'Shure MV7',
'External USB'];


// Mic glyph mirroring the MicGlyph above but tuned to MicSelector caps.
function MicLineGlyph({ size = 13, muted = false }) {
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none"
    stroke="currentColor" strokeWidth="1.3" strokeLinecap="square"
    aria-hidden="true" style={{ display: 'block', flexShrink: 0 }}>
      <rect x="6" y="2" width="4" height="8" />
      <path d="M3.5 8.5a4.5 4.5 0 0 0 9 0" />
      <line x1="8" y1="13" x2="8" y2="15" />
      <line x1="5.5" y1="15" x2="10.5" y2="15" />
      {muted && <line x1="2.5" y1="2.5" x2="13.5" y2="13.5" strokeWidth="1.6" />}
    </svg>);

}

function ChevGlyph({ size = 10 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 10 10" fill="none"
    stroke="currentColor" strokeWidth="1.2" strokeLinecap="square"
    aria-hidden="true" style={{ display: 'block', flexShrink: 0 }}>
      <path d="M2 3.5L5 1 8 3.5M2 6.5L5 9 8 6.5" />
    </svg>);

}

function StaticWaveform({ active, bars = 12 }) {
  // Static bars frozen at distinctive heights — visual placeholder for the
  // codebase's <LiveWaveform>. Heights are deterministic so it doesn't jiggle.
  const seq = [0.35, 0.78, 0.52, 0.92, 0.4, 0.66, 0.84, 0.3, 0.6, 0.74, 0.46, 0.88];
  return (
    <div className={`pp-micsel-wave ${active ? 'on' : ''}`}>
      {Array.from({ length: bars }).map((_, i) =>
      <span key={i} style={{ height: `${Math.round(seq[i % seq.length] * 100)}%` }} />
      )}
    </div>);

}

function MicSelector({ value, onChange, muted, onMutedChange }) {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef(null);

  useEffect(() => {
    if (!open) return;
    const onDocClick = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false);
    };
    const onEsc = (e) => {if (e.key === 'Escape') setOpen(false);};
    document.addEventListener('mousedown', onDocClick);
    document.addEventListener('keydown', onEsc);
    return () => {
      document.removeEventListener('mousedown', onDocClick);
      document.removeEventListener('keydown', onEsc);
    };
  }, [open]);

  return (
    <div className="pp-micsel-wrap" ref={wrapRef}>
      <button type="button"
      className={`pp-micsel ${open ? 'on' : ''}`}
      aria-expanded={open}
      onClick={() => setOpen((o) => !o)}>
        <MicLineGlyph muted={muted} />
        <span className="pp-micsel-label">{value}</span>
        <ChevGlyph />
      </button>
      {open &&
      <div className="pp-micsel-pop" role="dialog" aria-label="Audio input">
          <div className="pp-micsel-pop-list">
            {MOCK_INPUT_DEVICES.map((d) =>
          <button key={d} type="button"
          className={`pp-micsel-opt ${d === value ? 'on' : ''}`}
          onClick={() => {onChange(d);setOpen(false);}}>
                <span>{d}</span>
                {d === value && <span className="pp-micsel-check">✓</span>}
              </button>
          )}
          </div>
          <div className="pp-micsel-pop-foot">
            <button type="button"
          className="pp-micsel-mute"
          aria-pressed={muted}
          onClick={() => onMutedChange(!muted)}>
              <MicLineGlyph muted={muted} />
              <span>{muted ? 'UNMUTE' : 'MUTE'}</span>
            </button>
            <StaticWaveform active={!muted} />
          </div>
        </div>
      }
    </div>);

}

function ToolRow({ name, label, on, onToggle }) {
  return (
    <button type="button" className={`pp-tool ${on ? 'on' : 'off'}`} onClick={onToggle}>
      <span className="pp-tool-name">{name}</span>
      <span className="pp-tool-label">{label}</span>
      <span className={`pp-tool-status ${on ? 'on' : 'off'}`}>{on ? '● ON' : '○ OFF'}</span>
    </button>);

}

// ── ToolsButton ─────────────────────────────────────────────────────────────
// Wrench button on the call controls bar. Click to peek the currently-armed
// tools (derived from Settings). Greyed out when nothing's armed.

function ToolsButton({ tools, open, setOpen }) {
  const wrapRef = useRef(null);
  const active = (tools || []).filter((t) => t.on);
  const total = (tools || []).length;
  const allOff = active.length === 0;

  useEffect(() => {
    if (!open) return;
    const onDocClick = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false);
    };
    const onEsc = (e) => {if (e.key === 'Escape') setOpen(false);};
    document.addEventListener('mousedown', onDocClick);
    document.addEventListener('keydown', onEsc);
    return () => {
      document.removeEventListener('mousedown', onDocClick);
      document.removeEventListener('keydown', onEsc);
    };
  }, [open, setOpen]);

  return (
    <div className="pp-tools-wrap" ref={wrapRef}>
      <Btn small
      onClick={() => !allOff && setOpen(!open)}
      disabled={allOff}
      active={open}
      aria-label={allOff ? 'Tools — none armed' : `Tools — ${active.length} of ${total} armed`}
      aria-expanded={open}>
        <WrenchGlyph />
        {!allOff && <span className="pp-btn-badge">{active.length}</span>}
      </Btn>
      {open && !allOff &&
      <div className="pp-tools-pop" role="dialog" aria-label="Active tools">
          <div className="pp-tools-pop-hd">
            <span>ACTIVE TOOLS</span>
            <span className="pp-tools-pop-count">{active.length} / {total}</span>
          </div>
          <div className="pp-tools-pop-body">
            {active.map((t) =>
          <div key={t.name} className="pp-tools-pop-row">
                <span className="pp-tools-pop-name">{t.name}</span>
                <span className="pp-tools-pop-label">{t.label}</span>
              </div>
          )}
          </div>
          <div className="pp-tools-pop-foot">
            <span>↳ CONFIGURE IN SETTINGS</span>
          </div>
        </div>
      }
    </div>);
}

// ── ScrollArea ──────────────────────────────────────────────────────────────
// Hides native scrollbars, overlays a thin indicator bar that fades in on
// scroll/hover and fades out after idle — the behaviour macOS and iOS use on
// long text views and scroll views. Pure DOM math, no library.

function ScrollArea({ children, className = '', dark = false, contentClassName = '', ...rest }) {
  const scrollRef = useRef(null);
  const indicatorRef = useRef(null);
  const [show, setShow] = useState(false);
  const hideRef = useRef(null);

  useEffect(() => {
    const el = scrollRef.current;
    const ind = indicatorRef.current;
    if (!el || !ind) return;

    let raf = 0;
    const update = () => {
      const visible = el.clientHeight;
      const total = el.scrollHeight;
      if (total <= visible + 1) {
        ind.style.opacity = 0;
        ind.style.height = 0;
        return;
      }
      const ratio = visible / total;
      const h = Math.max(28, visible * ratio - 8);
      const max = visible - h - 8;
      const top = el.scrollTop / (total - visible) * max + 4;
      ind.style.height = h + 'px';
      ind.style.transform = `translateY(${top}px)`;
    };

    const flash = () => {
      setShow(true);
      clearTimeout(hideRef.current);
      hideRef.current = setTimeout(() => setShow(false), 900);
    };
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(update);
      flash();
    };
    const onEnter = () => {update();flash();};
    const onTouchStart = flash;

    el.addEventListener('scroll', onScroll, { passive: true });
    el.addEventListener('mouseenter', onEnter);
    el.addEventListener('touchstart', onTouchStart, { passive: true });
    el.addEventListener('wheel', flash, { passive: true });

    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    const mo = new MutationObserver(update);
    mo.observe(el, { childList: true, subtree: true, characterData: true });

    return () => {
      el.removeEventListener('scroll', onScroll);
      el.removeEventListener('mouseenter', onEnter);
      el.removeEventListener('touchstart', onTouchStart);
      el.removeEventListener('wheel', flash);
      ro.disconnect();
      mo.disconnect();
      clearTimeout(hideRef.current);
      cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <div className={`pp-scroll-wrap ${className}`} {...rest}>
      <div className={`pp-scroll-area ${contentClassName}`} ref={scrollRef}>
        {children}
      </div>
      <div className={`pp-scroll-indicator ${show ? 'on' : ''} ${dark ? 'dark' : ''}`} ref={indicatorRef} />
    </div>);
}

Object.assign(window, {
  CallView, PersonasView, ProvidersView, SettingsView, LangSwitch, resolvePersona,
  Btn, Tag, Hr, Spec, Label, FieldRow, SwitchRow, ToolRow, ScrollArea, ToolsButton,
  MicSelector,
  WaveGlyph, PhoneHangGlyph, MicGlyph, InterruptGlyph, WrenchGlyph, ScrollGlyph, SendGlyph,
  PERSONAS, PROVIDERS, TRANSCRIPT_SCRIPT, TOOLS_DEFAULT
});
