// Built with SVG + CSS so the visual stays sharp at any size.
// Exports: window.Orb

const ORB_STYLES = `
@keyframes pp-orb-breath {
  0%, 100% { transform: scale(0.96); }
  50% { transform: scale(1.04); }
}
@keyframes pp-orb-listen {
  0%, 100% { transform: scale(0.99); }
  50% { transform: scale(1.02); }
}
@keyframes pp-orb-speak {
  0% { transform: scale(0.94) rotate(0deg); }
  25% { transform: scale(1.07) rotate(2deg); }
  50% { transform: scale(0.97) rotate(-1deg); }
  75% { transform: scale(1.05) rotate(1deg); }
  100% { transform: scale(0.94) rotate(0deg); }
}
@keyframes pp-orb-spin { from { transform: rotate(0); } to { transform: rotate(360deg); } }
@keyframes pp-orb-spin-r { from { transform: rotate(360deg); } to { transform: rotate(0); } }
@keyframes pp-orb-noise { 0% { transform: translate(0,0); } 100% { transform: translate(-12px,-7px); } }
@keyframes pp-orb-ring {
  0% { transform: scale(1); opacity: 0.6; }
  100% { transform: scale(1.6); opacity: 0; }
}
@keyframes pp-bar {
  0%, 100% { transform: scaleY(0.25); }
  50% { transform: scaleY(1); }
}

.pp-orb {
  position: relative;
  display: inline-block;
  width: var(--pp-orb-size, 320px);
  height: var(--pp-orb-size, 320px);
  --pp-accent: #B0122F;
}
.pp-orb-core { width: 100%; height: 100%; position: relative; }
.pp-orb[data-state="idle"] .pp-orb-core { animation: pp-orb-breath 6s ease-in-out infinite; }
.pp-orb[data-state="listening"] .pp-orb-core { animation: pp-orb-listen 1.4s ease-in-out infinite; }
.pp-orb[data-state="speaking"] .pp-orb-core { animation: pp-orb-speak 2.2s ease-in-out infinite; }
.pp-orb[data-state="connecting"] .pp-orb-core { animation: pp-orb-breath 1.4s ease-in-out infinite; }
.pp-orb[data-state="ended"] .pp-orb-core { filter: grayscale(1) opacity(0.45); }

/* Ring pulse */
.pp-orb-ring {
  position: absolute; inset: 0;
  border: 1px solid currentColor;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
}
.pp-orb[data-state="listening"] .pp-orb-ring,
.pp-orb[data-state="speaking"]  .pp-orb-ring {
  animation: pp-orb-ring 2.4s ease-out infinite;
}
.pp-orb[data-state="speaking"] .pp-orb-ring-2 { animation-delay: 0.8s; }
.pp-orb[data-state="speaking"] .pp-orb-ring-3 { animation-delay: 1.6s; }

/* Gradient orb (default) — accent-driven two-tone, mirroring the codebase's
   ElevenLabs WebGL orb which renders [accent, shade(accent,-60)]. */
.pp-orb-grad {
  width: 100%; height: 100%; border-radius: 50%;
  background:
    radial-gradient(circle at 30% 30%, rgba(255,255,255,0.85), transparent 40%),
    conic-gradient(from 0deg,
      var(--pp-accent),
      color-mix(in srgb, var(--pp-accent) 55%, #000),
      var(--pp-accent),
      color-mix(in srgb, var(--pp-accent) 70%, #1a0006),
      var(--pp-accent));
  filter: blur(0.5px);
  position: relative; overflow: hidden;
}
.pp-orb-grad::before {
  content: ""; position: absolute; inset: -8%;
  background:
    radial-gradient(circle at 70% 60%, rgba(255,255,255,0.5), transparent 40%),
    radial-gradient(circle at 20% 80%, rgba(0,0,0,0.25), transparent 50%);
  animation: pp-orb-spin 14s linear infinite;
  mix-blend-mode: overlay;
}
.pp-orb-grad::after {
  content: ""; position: absolute; inset: 6%;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,0.55), transparent 55%);
  animation: pp-orb-spin-r 18s linear infinite;
}

/* Mono orb */
.pp-orb-mono {
  width: 100%; height: 100%; border-radius: 50%;
  background:
    radial-gradient(circle at 30% 30%, #ffffff, #c4c0b6 30%, #2a2926 75%, #060604 100%);
  position: relative; overflow: hidden;
}
.pp-orb-mono::before {
  content:""; position:absolute; inset:0; border-radius:50%;
  background-image:
    repeating-linear-gradient(45deg, transparent 0 6px, rgba(0,0,0,0.15) 6px 7px);
  mix-blend-mode: multiply;
}
.pp-orb-mono::after {
  content:""; position:absolute; inset:8%;
  border-radius:50%;
  border: 1px solid rgba(255,255,255,0.5);
  background: radial-gradient(circle at 40% 30%, rgba(255,255,255,0.7), transparent 45%);
}
.pp-orb.dark .pp-orb-mono {
  background:
    radial-gradient(circle at 30% 30%, #f4f2ed, #5a574e 30%, #161513 75%, #000 100%);
}

/* Particle orb */
.pp-orb-particle {
  width: 100%; height: 100%; border-radius: 50%;
  position: relative; overflow: hidden;
  background: radial-gradient(circle at 50% 50%, rgba(0,0,0,0.04), transparent 70%);
}
.pp-orb.dark .pp-orb-particle {
  background: radial-gradient(circle at 50% 50%, rgba(255,255,255,0.06), transparent 70%);
}
.pp-orb-particle svg { width: 100%; height: 100%; display: block; }

/* Soundbars under orb in listening */
.pp-bars {
  display: flex; align-items: end; justify-content: center;
  gap: 4px; height: 28px; margin-top: 22px;
}
.pp-bars > i {
  display: block; width: 3px; height: 100%;
  background: currentColor;
  transform-origin: center bottom;
  animation: pp-bar 0.9s ease-in-out infinite;
}
.pp-bars > i:nth-child(1) { animation-delay: -0.12s; }
.pp-bars > i:nth-child(2) { animation-delay: -0.36s; }
.pp-bars > i:nth-child(3) { animation-delay: -0.06s; }
.pp-bars > i:nth-child(4) { animation-delay: -0.48s; }
.pp-bars > i:nth-child(5) { animation-delay: -0.2s;  }
.pp-bars > i:nth-child(6) { animation-delay: -0.62s; }
.pp-bars > i:nth-child(7) { animation-delay: -0.32s; }
.pp-bars > i:nth-child(8) { animation-delay: -0.5s;  }
.pp-bars > i:nth-child(9) { animation-delay: -0.18s; }
.pp-bars > i:nth-child(10) { animation-delay: -0.42s; }

/* Manual-turn "hold" ring — shown only while LISTENING on a half-duplex engine
   (cascade STT) whose silence-gate / VAD is unreliable: the turn ends only when
   the user presses SEND. A held, slowly-rotating dashed ring reads differently
   from the expanding pulse rings, which imply automatic turn detection. */
.pp-orb-hold {
  position: absolute; inset: -7%;
  border: 1.5px dashed var(--pp-accent);
  border-radius: 50%;
  opacity: 0;
  pointer-events: none;
}
.pp-orb[data-manual="true"][data-state="listening"] .pp-orb-hold {
  animation: pp-orb-hold 9s linear infinite;
}
@keyframes pp-orb-hold {
  0%   { transform: rotate(0deg)   scale(1);    opacity: 0.7; }
  50%  { transform: rotate(180deg) scale(1.04); opacity: 0.95; }
  100% { transform: rotate(360deg) scale(1);    opacity: 0.7; }
}
/* Suppress the auto pulse rings in manual mode so the orb doesn't imply an
   automatic end-of-turn. */
.pp-orb[data-manual="true"][data-state="listening"] .pp-orb-ring {
  animation: none; opacity: 0;
}
@media (prefers-reduced-motion: reduce) {
  .pp-orb[data-manual="true"][data-state="listening"] .pp-orb-hold {
    animation: none; opacity: 0.85;
  }
}
`;

// inject once
(function injectOrbStyles() {
  if (typeof document === 'undefined') return;
  if (document.getElementById('pp-orb-styles')) return;
  const s = document.createElement('style');
  s.id = 'pp-orb-styles';
  s.textContent = ORB_STYLES;
  document.head.appendChild(s);
})();

// Pre-generate particle positions so they're stable across renders
function particles(seed, count) {
  // mulberry32
  let s = seed;
  const rng = () => {
    s |= 0; s = (s + 0x6D2B79F5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const out = [];
  for (let i = 0; i < count; i++) {
    // Distribute on disk with bias to edge
    const r = Math.sqrt(rng()) * 48;
    const a = rng() * Math.PI * 2;
    out.push({
      cx: 50 + Math.cos(a) * r,
      cy: 50 + Math.sin(a) * r,
      r: 0.3 + rng() * 1.4,
      o: 0.25 + rng() * 0.7,
      d: rng() * 4,
    });
  }
  return out;
}

const PARTICLES = particles(42, 280);

function Orb({ state = 'idle', style = 'gradient', size = 320, accent = '#B0122F', dark = false, manual = false }) {
  const wrapStyle = {
    '--pp-orb-size': typeof size === 'number' ? `${size}px` : size,
    '--pp-accent': accent,
    color: dark ? '#F4F2ED' : '#0A0A09',
  };

  let inner;
  if (style === 'mono') {
    inner = <div className="pp-orb-mono" />;
  } else if (style === 'particles') {
    inner = (
      <div className="pp-orb-particle">
        <svg viewBox="0 0 100 100">
          <defs>
            <radialGradient id="pp-pgrad" cx="50%" cy="50%" r="50%">
              <stop offset="0%"  stopColor={dark ? '#F4F2ED' : '#0A0A09'} stopOpacity="0.15" />
              <stop offset="55%" stopColor={accent} stopOpacity="0.55" />
              <stop offset="100%" stopColor={accent} stopOpacity="0" />
            </radialGradient>
          </defs>
          <circle cx="50" cy="50" r="48" fill="url(#pp-pgrad)" />
          {PARTICLES.map((p, i) => (
            <circle
              key={i}
              cx={p.cx} cy={p.cy} r={p.r}
              fill={dark ? '#F4F2ED' : '#0A0A09'}
              opacity={p.o}
            />
          ))}
        </svg>
      </div>
    );
  } else {
    inner = <div className="pp-orb-grad" />;
  }

  return (
    <div className={`pp-orb ${dark ? 'dark' : ''}`} data-state={state} data-manual={manual ? 'true' : 'false'} style={wrapStyle}>
      <div className="pp-orb-core">{inner}</div>
      <div className="pp-orb-ring pp-orb-ring-1" />
      <div className="pp-orb-ring pp-orb-ring-2" />
      <div className="pp-orb-ring pp-orb-ring-3" />
      <div className="pp-orb-hold" />
    </div>
  );
}

function Soundbars({ count = 10 }) {
  return (
    <div className="pp-bars">
      {Array.from({ length: count }).map((_, i) => <i key={i} />)}
    </div>
  );
}

window.Orb = Orb;
window.Soundbars = Soundbars;
