{"method":"get_file","path":"app.jsx","content":"// app.jsx — Desktop + Mobile app shells. Each owns its own call state but
// shares persona/provider selection across instances (via parent in mount.jsx).
// Exports to window: DesktopApp, MobileApp.

const { useState, useEffect, useRef } = React;

// ── Top bar (clock ticks live so the screen never feels frozen) ─────────────

function TopBar({ compact, callState, accent }) {
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(t);
  }, []);
  const hh = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  const ss = String(now.getSeconds()).padStart(2, '0');

  const live = !(callState === 'idle' || callState === 'ended');
  const sessionLabel = live ? 'LIVE' : (callState === 'ended' ? 'ENDED' : 'IDLE');
  const micLabel = live ? 'ON' : 'OFF';

  return (
    <header className="pp-topbar">
      <div className="pp-brand">
        <span className="pp-brand-mark" />
        <span className="pp-brand-name">TSUBAKI</span>
        {!compact && <span className="pp-brand-sub">v0.4.2 · realtime console</span>}
      </div>
      <div className="pp-topbar-status">
        <span>SESSION <b style={{ color: 'var(--ink)' }}>{sessionLabel}</b></span>
        {!compact && <span>NETWORK <b style={{ color: 'var(--ink)' }}>OK</b></span>}
        {!compact && <span>MIC <b style={{ color: 'var(--ink)' }}>{micLabel}</b></span>}
        <span style={{ fontVariantNumeric: 'tabular-nums' }}>{hh}:{mm}:{ss}</span>
      </div>
    </header>);

}

// ── Sidebar ─────────────────────────────────────────────────────────────────

const NAV = [
{ id: 'call', label: 'SESSIONS', key: 'C' },
{ id: 'personas', label: 'PERSONAS', key: 'P' },
{ id: 'providers', label: 'PROVIDERS', key: 'V' },
{ id: 'settings', label: 'SETTINGS', key: 'S' }];


function Sidebar({ nav, setNav, persona, provider, lang, callState }) {
  return (
    <nav className="pp-side">
      <div className="pp-side-eyebrow">— SECTIONS</div>
      {NAV.map((item) =>
      <button
        key={item.id}
        className={`pp-nav-item ${nav === item.id ? 'on' : ''}`}
        onClick={() => setNav(item.id)}>
          <span>{item.label}</span>
          <span className="pp-nav-key">{item.key}</span>
        </button>
      )}
      <div className="pp-side-foot">
        <div><b>{persona.name}</b> · {lang === 'ja' ? '日本語' : 'EN'}<br />active persona</div>
        <div><b>{provider.name}</b> · {provider.model}<br />active transport</div>
        <div>exec <b>{provider.exec ? provider.exec.toUpperCase() : 'REMOTE'}</b></div>
      </div>
    </nav>);

}

// ── Desktop App ─────────────────────────────────────────────────────────────

function DesktopApp({ tweaks }) {
  const [nav, setNav] = useState('call');
  const [callState, setCallState] = useState('listening'); // start in an interesting state
  // Session voice language. Upstream routes JA by agent id, so this is a
  // session property — not a per-card preview — and the armed persona is
  // derived from it rather than stored pre-resolved.
  const [lang, setLang] = useState('en');
  const [personaId, setPersonaId] = useState(PERSONAS[0].id);
  const persona = resolvePersona(PERSONAS.find((p) => p.id === personaId), lang);
  const setPersona = (p) => setPersonaId(p.id);
  const [provider, setProvider] = useState(PROVIDERS[0]);
  const [tools, setTools] = useState(TOOLS_DEFAULT);
  // Lifted from CallView so the MicSelector in SettingsView shares the same state
  // (matches the codebase's AppShell, which threads session.muted / toggleMute
  // through to both views).
  const [muted, setMuted] = useState(false);
  const [failover, setFailover] = useState(null);
  const failRef = useRef(false);

  // JA guarantee: whenever the armed persona speaks Japanese on a transport with
  // no JA agent (either side changed), reroute to the JA-capable transport
  // without dropping the session — brief CONNECTING dip, then resume.
  useEffect(() => {
    if (!(lang === 'ja' && !provider.ja) || failRef.current) return;
    failRef.current = true;
    const to = JA_PROVIDER();
    const live = !(callState === 'idle' || callState === 'ended');
    setFailover({ from: provider.name, to: to.name, phase: 'switching' });
    if (live) setCallState('connecting');
    setTimeout(() => {
      setProvider(to);
      if (live) setCallState('listening');
      setFailover((f) => f && { ...f, phase: 'done' });
    }, 1600);
    setTimeout(() => {setFailover(null);failRef.current = false;}, 5600);
  }, [lang, provider]);

  // pretend the agent shifts from speaking to listening after 5s on first load
  useEffect(() => {
    if (callState !== 'listening') return;
    const t = setTimeout(() => setCallState('speaking'), 5000);
    return () => clearTimeout(t);
  }, []);

  return (
    <div className={`pp-app ${tweaks.dark ? 'pp-dark' : ''}`} style={{ '--accent': tweaks.accent }}>
      <TopBar callState={callState} accent={tweaks.accent} />
      <div className="pp-shell">
        <Sidebar nav={nav} setNav={setNav}
        persona={persona} provider={provider} lang={lang}
        callState={callState} />
        <main className="pp-main">
          {nav === 'call' &&
          <CallView
            tweaks={tweaks}
            callState={callState}
            setCallState={setCallState}
            persona={persona}
            provider={provider}
            lang={lang}
            setLang={setLang}
            tools={tools}
            setTools={setTools}
            muted={muted}
            setMuted={setMuted}
            failover={failover}
            dark={tweaks.dark} />
          }
          {nav === 'personas' &&
          <PersonasView persona={persona} setPersona={setPersona} provider={provider}
          lang={lang} setLang={setLang}
          dark={tweaks.dark} accent={tweaks.accent} />
          }
          {nav === 'providers' &&
          <ProvidersView provider={provider} setProvider={setProvider}
          accent={tweaks.accent} />
          }
          {nav === 'settings' &&
          <SettingsView accent={tweaks.accent} tools={tools} setTools={setTools}
          muted={muted} setMuted={setMuted} />
          }
        </main>
      </div>
    </div>);

}

// ── Mobile App ──────────────────────────────────────────────────────────────

function MobileApp({ tweaks }) {
  const [nav, setNav] = useState('call');
  const [callState, setCallState] = useState('speaking');
