    if (callState === 'speaking') {setCaption(TRANSCRIPT_SCRIPT[TRANSCRIPT_SCRIPT.length - 1].text);return;}
    if (callState === 'interrupted') {setCaption('… you interrupted');return;}
  }, [callState]);

