{"method":"get_file","path":"styles.css","content":"/* ─────────────────────────────────────────────────────────────────────────
   PERSONA·PLEX — brutalist editorial styles.
   Mono everywhere, 1px hairlines, zero radius, ALL-CAPS tracked labels.
   All colors driven by CSS custom props so theme/accent tweak live.
   Scoped under .pp-app so it can't leak into the design canvas chrome.
   ───────────────────────────────────────────────────────────────────────── */

.pp-app {
  --bg:        #ECE9E1;
  --paper:     #F4F2ED;
  --ink:       #0A0A09;
  --ink-2:     #4A4842;
  --ink-3:     #8C8A82;
  --line:      #0A0A09;
  --hair:      rgba(10,10,9,0.16);
  --hair-2:    rgba(10,10,9,0.08);
  --accent:    #B0122F; /* camellia crimson (Tsubaki) — was burnt orange #C2410C */
  --accent-fg: #ffffff;

  width: 100%; height: 100%;
  background: var(--bg);
  color: var(--ink);
  font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 13px;
  line-height: 1.5;
  letter-spacing: 0;
  display: flex; flex-direction: column;
  overflow: hidden;
}

.pp-app.pp-dark {
  --bg:        #0A0A09;
  --paper:     #161513;
  --ink:       #F4F2ED;
  --ink-2:     #B8B5AC;
  --ink-3:     #6A685F;
  --line:      #F4F2ED;
  --hair:      rgba(244,242,237,0.22);
  --hair-2:    rgba(244,242,237,0.10);
}

/* ── Top bar ──────────────────────────────────────────────────────────── */

.pp-topbar {
  display: flex; align-items: center; gap: 24px;
  height: 48px; padding: 0 20px;
  border-bottom: 1px solid var(--line);
  background: var(--paper);
  flex: 0 0 auto;
}
.pp-brand {
  display: flex; align-items: baseline; gap: 8px;
  font-weight: 600; letter-spacing: 0.06em;
  font-size: 12px;
}
.pp-brand-mark {
  display: inline-block; width: 12px; height: 12px;
  background: var(--ink); position: relative;
}
.pp-brand-mark::after {
  content: ""; position: absolute;
  width: 6px; height: 6px;
  background: var(--accent);
  top: 3px; left: 3px;
}
.pp-brand-name { letter-spacing: 0.14em; }
.pp-brand-sub  { color: var(--ink-3); font-weight: 400; letter-spacing: 0.06em; font-size: 10px; }

.pp-topbar-status {
  display: flex; align-items: center; gap: 14px;
  margin-left: auto;
  font-size: 10px; letter-spacing: 0.08em; color: var(--ink-2);
}
.pp-topbar-status > span { display: inline-flex; align-items: center; gap: 6px; }

/* ── Layout ───────────────────────────────────────────────────────────── */

.pp-shell {
  flex: 1 1 auto; min-height: 0;
  display: grid;
  grid-template-columns: 184px 1fr;
  background: var(--bg);
}
.pp-side {
  border-right: 1px solid var(--line);
  background: var(--paper);
  display: flex; flex-direction: column;
  padding: 18px 0 12px;
  gap: 2px;
  font-size: 11px;
}
.pp-side-eyebrow {
  font-size: 9px; letter-spacing: 0.12em; color: var(--ink-3);
  padding: 0 18px 10px;
}
.pp-nav-item {
  appearance: none; background: transparent; border: 0;
  text-align: left; color: var(--ink-2);
  font: inherit; cursor: pointer;
  padding: 8px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  letter-spacing: 0.06em;
  border-left: 2px solid transparent;
  text-transform: uppercase;
}
.pp-nav-item:hover { background: var(--bg); color: var(--ink); }
.pp-nav-item.on {
  background: var(--bg);
  color: var(--ink);
  border-left-color: var(--accent);
  font-weight: 500;
}
.pp-nav-num  { color: var(--ink-3); font-size: 10px; }
.pp-nav-key  { color: var(--ink-3); font-size: 9px; padding: 1px 5px; border: 1px solid var(--hair); }

.pp-side-foot {
  margin-top: auto;
  padding: 12px 18px;
  border-top: 1px solid var(--hair);
  display: flex; flex-direction: column; gap: 6px;
  font-size: 10px; color: var(--ink-3); letter-spacing: 0.04em;
}
.pp-side-foot b { color: var(--ink); font-weight: 500; }

.pp-main {
  min-width: 0; min-height: 0;
  overflow: auto;
  position: relative;
  display: flex; flex-direction: column;
}

/* ── Page header ──────────────────────────────────────────────────────── */

.pp-page-hd {
  display: flex; justify-content: space-between; align-items: flex-end;
  gap: 24px;
  padding: 28px 28px 18px;
  border-bottom: 1px solid var(--line);
}
.pp-page-hd-r { display: flex; gap: 8px; flex: 0 0 auto; }

.pp-h-eyebrow {
  font-size: 10px; letter-spacing: 0.16em; color: var(--ink-3); text-transform: uppercase;
}
.pp-h1 {
  font-family: "Newsreader", ui-serif, Georgia, serif;
  font-size: 44px; font-weight: 400; letter-spacing: -0.01em;
  margin: 4px 0 6px;
  line-height: 1; font-style: italic;
}
.pp-lede {
  font-size: 12px; color: var(--ink-2); max-width: 56ch;
  margin: 0;
}

/* ── Primitives ───────────────────────────────────────────────────────── */

.pp-btn {
  appearance: none; cursor: pointer; font: inherit;
  background: var(--paper); color: var(--ink);
  border: 1px solid var(--line);
  padding: 8px 14px;
  letter-spacing: 0.08em; text-transform: uppercase;
  font-size: 11px; font-weight: 500;
  display: inline-flex; align-items: center; gap: 6px;
  transition: background 0.08s, color 0.08s, transform 0.04s;
  border-radius: 0;
}
.pp-btn:hover:not(:disabled) { background: var(--ink); color: var(--paper); }
.pp-btn:active:not(:disabled) { transform: translate(1px,1px); }
.pp-btn-sm { padding: 6px 10px; font-size: 10px; }
.pp-btn-on { background: var(--ink); color: var(--paper); }
.pp-btn-primary { background: var(--accent); color: var(--accent-fg); border-color: var(--accent); }
.pp-btn-primary:hover:not(:disabled) { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.pp-btn-danger { background: var(--paper); color: var(--ink); border-color: var(--line); }
.pp-btn:disabled { opacity: 0.35; cursor: not-allowed; }

/* Primed: the expected next action. Used on SEND while LISTENING on a manual-turn
   (cascade) engine, where the user must commit their turn because the silence
   gate / VAD is unreliable. Accent outline + a soft pulse so it reads as the
   thing to press. */
.pp-btn-primed:not(:disabled) {
  color: var(--accent);
  border-color: var(--accent);
  animation: pp-btn-primed 1.6s ease-in-out infinite;
}
.pp-btn-primed:not(:disabled):hover {
  background: var(--accent); color: var(--accent-fg); border-color: var(--accent);
}
@keyframes pp-btn-primed {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 45%, transparent); }
  60%      { box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent) 0%, transparent); }
}
@media (prefers-reduced-motion: reduce) {
  .pp-btn-primed:not(:disabled) { animation: none; }
}

.pp-tag {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 10px; letter-spacing: 0.1em;
  padding: 3px 7px;
  border: 1px solid var(--hair);
  color: var(--ink-2);
  background: transparent;
  text-transform: uppercase;
  white-space: nowrap;
}
.pp-tag-mono { font-variant-numeric: tabular-nums; }
.pp-tag-accent { color: var(--accent); border-color: var(--accent); }
.pp-dot {
  display: inline-block;
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
}

.pp-hr  { border: 0; border-top: 1px solid var(--hair); margin: 14px 0; }
.pp-hr-l { display: flex; align-items: center; gap: 10px; margin: 22px 0 12px; }
.pp-hr-line { flex: 1 1 auto; height: 1px; background: var(--hair); }
.pp-hr-label { font-size: 10px; letter-spacing: 0.14em; color: var(--ink-3); }

.pp-spec {
  border: 1px solid var(--hair);
  padding: 12px 14px;
  background: var(--paper);
}
.pp-spec-l { font-size: 9px; letter-spacing: 0.14em; color: var(--ink-3); }
.pp-spec-v { font-size: 13px; color: var(--ink); margin-top: 4px; }
.pp-spec-s { font-size: 10px; color: var(--ink-3); margin-top: 2px; }

.pp-label { font-size: 10px; letter-spacing: 0.12em; color: var(--ink-3); text-transform: uppercase; }
.pp-label-n { color: var(--accent); margin-right: 6px; }

.pp-mono-num { font-variant-numeric: tabular-nums; color: var(--ink-2); }

/* ── Call view ────────────────────────────────────────────────────────── */

.pp-call {
  flex: 1 1 auto; min-height: 0;
  display: grid;
  grid-template-columns: 1fr auto;
  position: relative;
}
.pp-call-stage {
  position: relative;
  display: flex; flex-direction: column;
  padding: 28px 28px 24px;
  min-width: 0;
  min-height: 0;
}

.pp-call-meta {
  display: flex; justify-content: space-between; align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px dashed var(--hair);
  flex: 0 0 auto;
}
.pp-call-meta-l, .pp-call-meta-r { display: flex; gap: 8px; align-items: center; }

/* 50/50 vertical split — orb half on top, caption half on bottom. */
.pp-call-body {
  flex: 1 1 auto; min-height: 0;
  display: grid;
  grid-template-rows: 1fr 1fr;
  gap: 0;
}

/* Orb half: orb-fit fills the available square, soundbars + state sit under */
.pp-orb-area {
  min-height: 0;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  gap: 12px;
  padding: 16px 0;
  color: var(--ink);
  position: relative;
  container-type: size;
}
.pp-orb-area::before, .pp-orb-area::after {
  /* corner ticks framing the orb area */
  content: ""; position: absolute;
  width: 22px; height: 22px;
  border: 1px solid var(--hair);
}
.pp-orb-area::before { top: 8px; left: 8px; border-right: 0; border-bottom: 0; }
.pp-orb-area::after  { bottom: 8px; right: 8px; border-left: 0; border-top: 0; }
.pp-orb-fit {
  /* fit the largest possible square in the remaining cqh/cqw, capped at 320px */
  width: min(100cqh - 80px, 100cqw - 32px, 320px);
  height: min(100cqh - 80px, 100cqw - 32px, 320px);
  flex: 0 0 auto;
  display: grid;
  place-items: center;
}
.pp-orb-fit > .pp-orb {
  --pp-orb-size: 100%;
}

/* Caption half — scrollable text area, centred when short. */
.pp-caption-area {
  min-height: 0;
  display: flex;
  border-top: 1px dashed var(--hair);
  padding-top: 8px;
}
.pp-caption-scroll {
  width: 100%;
  height: 100%;
}
.pp-caption-scroll .pp-scroll-area {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px 28px;
}

.pp-call-state {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  margin-top: 8px;
  font-size: 11px; letter-spacing: 0.18em; text-transform: uppercase;
}
.pp-call-state-l { font-weight: 600; color: var(--ink); }
.pp-call-state-sub { color: var(--ink-3); font-size: 10px; letter-spacing: 0.08em; }
/* Manual-turn hint — the silence gate is off on this engine, so the user ends
   their turn with SEND. Shown under the orb state while listening on cascade. */
.pp-call-manual-hint {
  margin-top: 6px;
  font-size: 9.5px; letter-spacing: 0.2em; text-transform: uppercase;
  color: var(--accent);
  text-align: center;
}
.pp-call-state-dot {
  width: 8px; height: 8px;
  background: var(--ink-3);
  position: relative;
}
.pp-state-listening, .pp-state-speaking, .pp-state-connecting, .pp-state-interrupted {
  background: var(--accent);
}
.pp-state-listening::before, .pp-state-speaking::before, .pp-state-connecting::before {
  content: ""; position: absolute; inset: 0;
  background: var(--accent);
  animation: pp-orb-ring 1.6s ease-out infinite;
}
.pp-state-ended { background: var(--ink-3); }

.pp-caption {
  display: flex; justify-content: center; align-items: baseline; gap: 6px;
  font-family: "Newsreader", ui-serif, Georgia, serif;
  font-style: italic;
  font-size: 19px;
  color: var(--ink);
  text-align: center;
  padding: 0;
  max-width: 60ch;
  animation: pp-caption-in 0.4s ease both;
}
@keyframes pp-caption-in {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: none; }
}
.pp-caption-q { color: var(--accent); font-size: 28px; line-height: 0.6; }
.pp-caption-t { text-wrap: pretty; }

.pp-controls {
  display: flex; justify-content: center; gap: 10px;
  margin-top: 0;
  padding-top: 18px;
  border-top: 1px solid var(--hair);
  flex-wrap: wrap;
  flex: 0 0 auto;
}

/* Transcript drawer */
.pp-transcript {
  width: 0;
  border-left: 1px solid var(--line);
  background: var(--paper);
  overflow: hidden;
  transition: width 0.24s ease;
  flex: 0 0 auto;
  display: flex; flex-direction: column;
}
.pp-transcript.open { width: 340px; }
.pp-transcript-hd {
  display: flex; justify-content: space-between; align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--hair);
  font-size: 10px; letter-spacing: 0.12em;
  color: var(--ink-3);
  flex: 0 0 auto;
}
.pp-h-meta { color: var(--ink-3); }
.pp-transcript-scroll {
  flex: 1 1 auto;
  min-height: 0;
}
.pp-transcript-scroll .pp-scroll-area { padding: 0; }
.pp-transcript-body {
  padding: 16px;
  display: flex; flex-direction: column; gap: 14px;
}
.pp-turn { display: flex; flex-direction: column; gap: 4px; }
.pp-turn-hd {
  display: flex; justify-content: space-between;
  font-size: 9px; letter-spacing: 0.1em; color: var(--ink-3);
  text-transform: uppercase;
}
.pp-turn-who { color: var(--ink); font-weight: 500; }
.pp-turn-user .pp-turn-who { color: var(--accent); }
.pp-turn-text {
  font-family: "Newsreader", ui-serif, Georgia, serif;
  font-style: italic;
  font-size: 15px;
  color: var(--ink);
  text-wrap: pretty;
}
.pp-turn-user .pp-turn-text { color: var(--ink-2); }
.pp-turn-live .pp-turn-text { min-height: 24px; }
.pp-cursor {
  display: inline-block; width: 8px; height: 16px;
  background: var(--accent);
  vertical-align: -3px;
  animation: pp-cursor 1s steps(2) infinite;
}
@keyframes pp-cursor { 50% { opacity: 0; } }

/* ── ScrollArea — auto-hiding macOS/iOS-style indicator ────────────────── */

.pp-scroll-wrap {
  position: relative;
  overflow: hidden;
  min-height: 0;
}
.pp-scroll-area {
  width: 100%;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.pp-scroll-area::-webkit-scrollbar { width: 0; height: 0; display: none; }
.pp-scroll-indicator {
  position: absolute;
  top: 0; right: 3px;
  width: 4px;
  background: rgba(10, 10, 9, 0.45);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.32s ease;
  /* Brutalist: no border-radius. Hard edges. */
}
.pp-scroll-indicator.on { opacity: 1; }
.pp-scroll-indicator.dark { background: rgba(244, 242, 237, 0.55); }
.pp-app.pp-dark .pp-scroll-indicator { background: rgba(244, 242, 237, 0.55); }

/* ── Personas ─────────────────────────────────────────────────────────── */

.pp-personas { padding: 0; }
.pp-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 0;
  border-bottom: 1px solid var(--line);
}
.pp-persona-card {
  padding: 16px 18px 18px;
  border-right: 1px solid var(--hair);
  border-bottom: 1px solid var(--hair);
  background: var(--paper);
  cursor: pointer;
  display: flex; flex-direction: column;
  position: relative;
  min-height: 240px;
  transition: background 0.1s;
}
.pp-persona-card:hover { background: var(--bg); }
.pp-persona-card.on {
  background: var(--bg);
  outline: 1px solid var(--accent);
  outline-offset: -2px;
}
.pp-persona-top {
  display: flex; justify-content: space-between; align-items: flex-start;
  margin-bottom: 12px;
}
.pp-persona-num {
  font-size: 10px; letter-spacing: 0.1em; color: var(--ink-3);
  font-variant-numeric: tabular-nums;
}
.pp-persona-dot {
  width: 14px; height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
  margin: 3px 3px 0 0;
  transition: background 0.15s ease, box-shadow 0.15s ease;
}
.pp-persona-name {
  font-size: 18px; letter-spacing: 0.06em;
  font-weight: 500;
  margin-bottom: 2px;
}
.pp-persona-accent {
  font-size: 10px; letter-spacing: 0.1em;
  color: var(--ink-3);
  margin-bottom: 10px;
}
.pp-persona-traits {
  display: flex; flex-wrap: wrap; gap: 4px;
  margin-bottom: 10px;
}
.pp-trait {
  white-space: nowrap; word-break: keep-all;
  font-size: 9px; letter-spacing: 0.1em;
  padding: 2px 6px;
  border: 1px solid var(--hair);
  color: var(--ink-2);
}
.pp-persona-desc {
  font-family: "Newsreader", ui-serif, Georgia, serif;
  font-size: 13px; color: var(--ink-2);
  font-style: italic;
  margin: 0 0 12px;
  flex: 1 1 auto;
  text-wrap: pretty;
}
.pp-persona-foot {
  display: flex; justify-content: space-between;
  border-top: 1px dashed var(--hair);
  padding-top: 8px;
  font-size: 10px;
}
.pp-persona-active {
  position: absolute; top: 14px; right: 14px;
  font-size: 9px; letter-spacing: 0.12em;
  color: var(--accent);
}
.pp-persona-empty {
  background: repeating-linear-gradient(45deg,
    transparent 0 8px, var(--hair-2) 8px 9px);
}
.pp-persona-empty .pp-persona-name { color: var(--ink-3); }
.pp-persona-drop {
  border: 1px dashed var(--hair);
  padding: 18px;
  text-align: center;
  font-size: 10px; letter-spacing: 0.1em; color: var(--ink-3);
  margin-top: auto;
}

/* ── Providers ────────────────────────────────────────────────────────── */

.pp-providers { padding: 0 0 24px; }

.pp-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
}
.pp-table thead th {
  text-align: left;
  font-size: 9px; letter-spacing: 0.12em; color: var(--ink-3);
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
  background: var(--paper);
  font-weight: 500;
}
.pp-table tbody tr {
  border-bottom: 1px solid var(--hair);
  cursor: pointer;
  transition: background 0.08s;
}
.pp-table tbody tr:hover { background: var(--paper); }
.pp-table tbody tr.on {
  background: var(--paper);
  outline: 1px solid var(--accent);
  outline-offset: -1px;
}
.pp-table td { padding: 12px 14px; vertical-align: middle; }
.pp-table-vendor { font-weight: 600; letter-spacing: 0.04em; }
.pp-table-note  { color: var(--ink-3); font-size: 10px; }
.pp-table-radio span {
  display: inline-block;
  width: 12px; height: 12px;
  border: 1px solid var(--line);
  position: relative;
}
.pp-table-radio span.on::after {
  content: ""; position: absolute; inset: 2px;
  background: var(--accent-fg);
}

.pp-prov-detail { padding: 8px 28px 0; }
.pp-prov-specs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}

/* Per-provider model-picker inset — a detail row under a provider whose engine
   has a multi-model catalog (cascade). Single-model providers render no inset.
   The inset itself stays a real table-cell (so colSpan spans the full row); the
   flex layout lives on an inner wrapper — a flex `td` would drop out of the
   table box model and shrink to its content. */
.pp-prov-inset-row { cursor: default; }
.pp-prov-inset-row.on { outline: 1px solid var(--accent); outline-offset: -1px; }
.pp-prov-inset {
  padding: 8px 14px 10px !important;
  background: var(--hair-2);
  border-bottom: 1px solid var(--hair);
}
.pp-prov-inset-inner {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
}
.pp-prov-inset-l {
  font-size: 9px; letter-spacing: 0.14em; color: var(--ink-3);
  text-transform: uppercase; flex: 0 0 auto;
}
.pp-prov-models { display: flex; flex-wrap: wrap; gap: 6px; }
.pp-prov-model {
  appearance: none; cursor: pointer; font: inherit;
  font-size: 10px; letter-spacing: 0.04em;
  padding: 4px 9px;
  background: var(--paper); color: var(--ink-2);
  border: 1px solid var(--hair); border-radius: 0;
  transition: background 0.08s, color 0.08s, border-color 0.08s;
}
.pp-prov-model:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.pp-prov-model.on { font-weight: 600; }

/* ── Settings ─────────────────────────────────────────────────────────── */

.pp-settings { padding: 0 0 24px; }
.pp-settings-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-top: 1px solid var(--line);
}
.pp-settings-sec {
  padding: 18px 28px 20px;
  border-right: 1px solid var(--hair);
  border-bottom: 1px solid var(--hair);
}
.pp-field { margin-bottom: 14px; }
.pp-field-hd {
  display: flex; justify-content: space-between;
  font-size: 9px; letter-spacing: 0.12em; color: var(--ink-3);
  text-transform: uppercase;
  margin-bottom: 6px;
}
.pp-field-hint { color: var(--ink-2); font-variant-numeric: tabular-nums; }

.pp-select {
  appearance: none;
  background: var(--paper);
  border: 1px solid var(--line);
  font: inherit; color: var(--ink);
  padding: 7px 24px 7px 10px;
  font-size: 11px;
  width: 100%;
  border-radius: 0;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path fill='currentColor' d='M0 0h10L5 6z'/></svg>");
  background-repeat: no-repeat;
  background-position: right 8px center;
}

.pp-meter {
  height: 8px;
  border: 1px solid var(--line);
  background:
    repeating-linear-gradient(90deg,
      var(--hair-2) 0 1px, transparent 1px 12px);
  position: relative;
  overflow: hidden;
}
.pp-meter > span { display: block; height: 100%; }

.pp-range { width: 100%; }
.pp-range-scale {
  display: flex; justify-content: space-between;
  font-size: 9px; color: var(--ink-3);
  margin-top: 4px;
}

.pp-switch {
  appearance: none; border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
  font: inherit; font-size: 9px; letter-spacing: 0.14em;
  cursor: pointer;
  display: inline-grid;
  grid-template-columns: 1fr 22px 1fr;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border-radius: 0;
}
.pp-switch-l, .pp-switch-r { color: var(--ink-3); }
.pp-switch.on .pp-switch-r { color: var(--accent); font-weight: 600; }
.pp-switch:not(.on) .pp-switch-l { color: var(--ink); font-weight: 600; }
.pp-switch-knob {
  display: inline-block;
  width: 14px; height: 8px;
  background: var(--ink-3);
  position: relative;
}
.pp-switch.on .pp-switch-knob { background: var(--accent); }
.pp-switch-knob::after {
  content: ""; position: absolute;
  width: 6px; height: 12px;
  top: -2px; left: 0;
  background: var(--paper);
  border: 1px solid var(--line);
  transition: left 0.12s;
}
.pp-switch.on .pp-switch-knob::after { left: 8px; }

.pp-tool {
  display: grid;
  grid-template-columns: 130px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 8px 0;
  border: 0;
  border-bottom: 1px dashed var(--hair);
  background: transparent;
  width: 100%;
  font: inherit;
  text-align: left;
  color: var(--ink);
  font-size: 11px;
  cursor: pointer;
  transition: background 0.08s, opacity 0.12s;
}
.pp-tool:hover { background: var(--hair-2); }
.pp-tool.off { opacity: 0.55; }
.pp-tool:last-child { border-bottom: 0; }
.pp-tool-name { color: var(--accent); font-weight: 500; }
.pp-tool-label { color: var(--ink-2); }
.pp-tool-status { font-size: 9px; letter-spacing: 0.12em; }
.pp-tool-status.on  { color: var(--ink); }
.pp-tool-status.off { color: var(--ink-3); }

/* ── ToolsButton popover ──────────────────────────────────────────────── */

.pp-tools-wrap {
  position: relative;
  display: inline-flex;
}
.pp-btn-badge {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 13px; height: 13px;
  background: var(--accent); color: var(--accent-fg);
  font-size: 9px; font-weight: 600;
  letter-spacing: 0;
  padding: 0 3px;
  margin-left: 4px;
  font-variant-numeric: tabular-nums;
}
.pp-btn:hover:not(:disabled) .pp-btn-badge,
.pp-btn-on .pp-btn-badge {
  background: var(--accent-fg);
  color: var(--accent);
}
.pp-tools-pop {
  position: absolute;
  bottom: calc(100% + 8px);
  right: 0;
  min-width: 280px;
  background: var(--paper);
  border: 1px solid var(--line);
  box-shadow: 4px 4px 0 var(--line);
  z-index: 50;
  font-size: 11px;
  animation: pp-pop-in 0.16s ease-out both;
}
@keyframes pp-pop-in {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: none; }
}
.pp-tools-pop::after {
  /* small notch pointing down at the button */
  content: ""; position: absolute;
  top: 100%; right: 14px;
  width: 8px; height: 8px;
  background: var(--paper);
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  transform: translateY(-50%) rotate(45deg);
}
.pp-tools-pop-hd {
  display: flex; justify-content: space-between; align-items: center;
  padding: 8px 12px;
  font-size: 9px; letter-spacing: 0.14em;
  color: var(--ink-3);
  text-transform: uppercase;
  border-bottom: 1px solid var(--hair);
}
.pp-tools-pop-count { color: var(--ink-2); font-variant-numeric: tabular-nums; }
.pp-tools-pop-body {
  display: flex; flex-direction: column;
}
.pp-tools-pop-row {
  display: flex; justify-content: space-between; align-items: baseline;
  gap: 16px;
  padding: 8px 12px;
  border-bottom: 1px dashed var(--hair);
}
.pp-tools-pop-row:last-child { border-bottom: 0; }
.pp-tools-pop-name {
  color: var(--accent);
  font-weight: 500;
  font-size: 11px;
}
.pp-tools-pop-label {
  color: var(--ink-2);
  font-size: 10px;
  text-align: right;
}
.pp-tools-pop-foot {
  padding: 8px 12px;
  border-top: 1px solid var(--hair);
  font-size: 9px; letter-spacing: 0.14em;
  color: var(--ink-3);
}

/* ── Mobile ───────────────────────────────────────────────────────────── */

.pp-mobile {
  width: 100%; height: 100%;
  display: flex; flex-direction: column;
  background: var(--bg);
  color: var(--ink);
  position: relative;
  overflow: hidden;
}
.pp-mobile .pp-topbar {
  height: 38px; padding: 0 14px;
  font-size: 10px;
}
.pp-mobile-status {
  display: flex; justify-content: space-between; align-items: center;
  padding: 6px 14px;
  border-bottom: 1px solid var(--hair);
  font-size: 9px; letter-spacing: 0.1em; color: var(--ink-3);
}
.pp-mobile-stage {
  flex: 1 1 auto; min-height: 0;
  display: flex; flex-direction: column;
  padding: 14px 14px 12px;
  position: relative;
}
.pp-mobile-stage-top {
  display: flex; justify-content: flex-end;
  margin-bottom: 6px;
  flex: 0 0 auto;
}
.pp-mobile-body {
  flex: 1 1 auto; min-height: 0;
  display: grid;
  grid-template-rows: 1fr 1fr;
}
.pp-mobile-orb-area {
  padding: 8px 0;
  gap: 8px;
}
.pp-mobile-orb-fit {
  width: min(100cqh - 56px, 100cqw - 24px, 220px);
  height: min(100cqh - 56px, 100cqw - 24px, 220px);
}
.pp-mobile-caption-area {
  padding-top: 6px;
}
.pp-mobile-caption-area .pp-scroll-area {
  padding: 8px 8px;
  display: flex;
  align-items: flex-start;
  justify-content: center;
}
.pp-mobile-caption {
  font-family: "Newsreader", ui-serif, Georgia, serif;
  font-style: italic;
  font-size: 17px;
  color: var(--ink);
  text-align: center;
  padding: 0 4px;
  text-wrap: pretty;
  margin: 0;
}
.pp-mobile-state {
  font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--ink-2);
  display: flex; align-items: center; gap: 8px;
}
.pp-mobile-controls {
  display: flex; justify-content: center; gap: 8px;
  padding: 14px 14px;
  border-top: 1px solid var(--line);
  background: var(--paper);
}
.pp-mobile-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line);
  background: var(--paper);
}
.pp-mobile-tab {
  appearance: none; background: transparent; border: 0;
  font: inherit; color: var(--ink-2);
  padding: 10px 4px;
  font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase;
  border-right: 1px solid var(--hair);
  cursor: pointer;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
}
.pp-mobile-tab:last-child { border-right: 0; }
.pp-mobile-tab.on {
  color: var(--ink);
  background: var(--bg);
  font-weight: 600;
  position: relative;
}
.pp-mobile-tab.on::before {
  content: ""; position: absolute; top: -1px; left: 0; right: 0;
  height: 2px; background: var(--accent);
}
.pp-mobile-tab-n { font-size: 8px; color: var(--ink-3); }

.pp-mobile-sheet {
  position: absolute; left: 0; right: 0; bottom: 0;
  background: var(--paper);
  border-top: 1px solid var(--line);
  transform: translateY(calc(100% - 32px));
  transition: transform 0.28s cubic-bezier(.2,.7,.3,1);
  z-index: 5;
  max-height: 70%;
  display: flex; flex-direction: column;
}
.pp-mobile-sheet.open { transform: translateY(0); }
.pp-mobile-sheet-handle {
  text-align: center;
  font-size: 9px; letter-spacing: 0.16em; color: var(--ink-3);
  padding: 8px;
  border-bottom: 1px solid var(--hair);
  cursor: pointer;
}
.pp-mobile-sheet-scroll {
  flex: 1 1 auto;
  min-height: 0;
}
.pp-mobile-sheet-scroll .pp-scroll-area { padding: 0; }
.pp-mobile-sheet-body {
  padding: 14px;
  display: flex; flex-direction: column; gap: 12px;
}

.pp-mobile .pp-persona-card { min-height: 160px; padding: 12px; }
.pp-mobile .pp-h1 { font-size: 26px; }
.pp-mobile .pp-page-hd { padding: 14px; }
.pp-mobile .pp-lede { font-size: 11px; }
.pp-mobile .pp-table { font-size: 10px; }
.pp-mobile .pp-table td, .pp-mobile .pp-table th { padding: 8px 10px; }
.pp-mobile .pp-settings-grid { grid-template-columns: 1fr; }
.pp-mobile .pp-settings-sec { padding: 14px; }

/* Brutalist override for the ElevenLabs BarVisualizer bars (in case any
   live-audio variant lands in the design — squares off rounded bars). */
.pp-elbars [data-bar],
.pp-elbars span { border-radius: 0 !important; }

/* ── MicSelector ─────────────────────────────────────────────────────────
   Mic icon (toggles mute) + device label + chevron. Brutalist popover lists
   available devices and exposes a static waveform preview. Mirrors the
   codebase's ElevenLabs-derived MicSelector. */

.pp-micsel-wrap { position: relative; display: inline-flex; width: 100%; }
.pp-micsel {
  appearance: none; font: inherit;
  display: inline-flex; align-items: center; gap: 8px;
  width: 100%; min-width: 0;
  padding: 7px 10px;
  background: var(--paper);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 0;
  cursor: pointer;
  font-size: 11px;
  letter-spacing: 0.02em;
  transition: background 0.08s, color 0.08s;
}
.pp-micsel:hover { background: var(--bg); }
.pp-micsel.on { background: var(--ink); color: var(--paper); }
.pp-micsel-label {
  flex: 1 1 auto; min-width: 0;
  overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  text-align: left;
}
.pp-micsel-pop {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 0; right: 0;
  background: var(--paper);
  border: 1px solid var(--line);
  box-shadow: 4px 4px 0 var(--line);
  z-index: 50;
  font-size: 11px;
  animation: pp-pop-in 0.16s ease-out both;
}
.pp-micsel-pop-list { display: flex; flex-direction: column; }
.pp-micsel-opt {
  appearance: none; font: inherit;
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  padding: 9px 12px;
  background: transparent; border: 0;
  border-bottom: 1px dashed var(--hair);
  color: var(--ink-2);
  text-align: left;
  cursor: pointer;
  letter-spacing: 0.02em;
  width: 100%;
}
.pp-micsel-opt:hover { background: var(--bg); color: var(--ink); }
.pp-micsel-opt.on { color: var(--ink); font-weight: 500; }
.pp-micsel-opt:last-child { border-bottom: 0; }
.pp-micsel-check { color: var(--accent); font-weight: 600; }
.pp-micsel-pop-foot {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px;
  border-top: 1px solid var(--hair);
  background: var(--paper);
}
.pp-micsel-mute {
  appearance: none; font: inherit;
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 9px;
  background: transparent; color: var(--ink);
  border: 1px solid var(--hair);
  border-radius: 0;
  cursor: pointer;
  font-size: 10px;
  letter-spacing: 0.12em;
}
.pp-micsel-mute:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.pp-micsel-mute[aria-pressed="true"] {
  background: var(--accent); color: var(--accent-fg); border-color: var(--accent);
}
.pp-micsel-wave {
  margin-left: auto;
  display: flex; align-items: center; gap: 1px;
  width: 70px; height: 22px;
  padding: 0 4px;
  background: var(--hair-2);
  border: 1px solid var(--hair);
  opacity: 0.45;
  transition: opacity 0.16s;
}
.pp-micsel-wave.on { opacity: 1; }
.pp-micsel-wave > span {
  display: block;
  flex: 1 1 auto; min-width: 0;
  background: var(--accent);
  align-self: center;
  min-height: 2px;
}

/* ── Persona language variants (EN / 日本語) ──────────────────────────── */
.pp-ja { font-family: "Zen Kaku Gothic New", "Hiragino Kaku Gothic ProN", "Noto Sans JP", "Yu Gothic", sans-serif; }
.pp-persona-desc.pp-ja { font-family: "Shippori Mincho", "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif JP", serif; font-size: 12.5px; line-height: 1.85; }
.pp-persona-top-r { display: flex; align-items: center; gap: 10px; }
.pp-lang-sw { display: inline-flex; border: 1px solid var(--hair); }
.pp-lang-btn { white-space: nowrap; font-family: inherit; font-size: 9px; letter-spacing: 0.08em; line-height: 1; padding: 3px 7px; background: none; border: 0; color: var(--ink-3); cursor: pointer; }
.pp-lang-btn + .pp-lang-btn { border-left: 1px solid var(--hair); }
.pp-lang-btn.on { background: var(--ink); color: var(--bg); }
.pp-persona-name .pp-name-sub { font-size: 10px; letter-spacing: 0.12em; color: var(--ink-3); margin-left: 8px; font-weight: 400; }
.pp-ja-support { display: flex; justify-content: space-between; gap: 8px; font-size: 9px; letter-spacing: 0.08em; margin-bottom: 8px; }
.pp-ja-support-l { color: var(--ink-3); white-space: nowrap; }
.pp-ja-support-v { color: var(--ink-2); text-align: right; }
.pp-ja-greet { display: flex; flex-direction: column; gap: 4px; border-left: 1px solid var(--hair); padding-left: 9px; margin-bottom: 10px; }
.pp-ja-greet-l { display: flex; gap: 7px; font-size: 8px; letter-spacing: 0.14em; color: var(--ink-3); }
.pp-ja-greet-tag { color: var(--accent); }
.pp-ja-greet-t { font-family: "Shippori Mincho", "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif JP", serif; font-size: 11.5px; line-height: 1.8; color: var(--ink-2); }
.pp-ja-warn { font-size: 9px; letter-spacing: 0.08em; color: var(--accent); border: 1px dashed var(--accent); padding: 5px 7px; margin-bottom: 8px; }
.pp-ja-mark { font-size: 8px; letter-spacing: 0.12em; border: 1px solid var(--hair); padding: 1px 4px; margin-left: 8px; color: var(--ink-3); }
/* Session voice-language control, paired with its label in a page header. */
.pp-lang-field { display: inline-flex; align-items: center; gap: 8px; margin-right: 4px; }
.pp-lang-field-l { font-size: 9px; letter-spacing: 0.14em; color: var(--ink-3); white-space: nowrap; }
.pp-mobile-stage-top { justify-content: space-between; gap: 8px; }
.pp-mobile .pp-lang-btn { padding: 3px 5px; }
.pp-mobile .pp-persona-top-r { gap: 6px; }
.pp-mobile .pp-ja-warn { margin-top: 8px; margin-bottom: 0; }

/* Transport failover strip (JA reroute) */
.pp-failover { font-size: 10px; letter-spacing: 0.1em; padding: 7px 10px; margin: 0 0 10px; border: 1px dashed var(--accent); color: var(--accent); animation: pp-failover-in 0.15s ease; }
.pp-failover.done { border-style: solid; }
@keyframes pp-failover-in { from { opacity: 0; transform: translateY(-2px); } to { opacity: 1; transform: none; } }
.pp-mobile .pp-failover { margin: 0 14px 8px; }
